(** [veriwasm::opiter::binary_types]:
    Source: 'src/opiter.rs', lines 1151:0-1250:1 *)
Definition opiter_binary_types
  (opcode : u8) : result (option (types_ValueType_t * types_ValueType_t)) :=
  if opcode s= opiter_op_i32_eq
  then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
  else
    if opcode s= opiter_op_i32_ne
    then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
    else
      if opcode s= opiter_op_i32_lt_s
      then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
      else
        if opcode s= opiter_op_i32_lt_u
        then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
        else
          if opcode s= opiter_op_i32_gt_s
          then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
          else
            if opcode s= opiter_op_i32_gt_u
            then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
            else
              if opcode s= opiter_op_i32_le_s
              then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
              else
                if opcode s= opiter_op_i32_le_u
                then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
                else
                  if opcode s= opiter_op_i32_ge_s
                  then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
                  else
                    if opcode s= opiter_op_i32_ge_u
                    then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
                    else
                      if opcode s= opiter_op_i32_add
                      then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
                      else
                        if opcode s= opiter_op_i32_sub
                        then
                          Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
                        else
                          if opcode s= opiter_op_i32_mul
                          then
                            Ok (Some (Types_ValueType_I32,
                              Types_ValueType_I32))
                          else
                            if opcode s= opiter_op_i32_div_s
                            then
                              Ok (Some (Types_ValueType_I32,
                                Types_ValueType_I32))
                            else
                              if opcode s= opiter_op_i32_div_u
                              then
                                Ok (Some (Types_ValueType_I32,
                                  Types_ValueType_I32))
                              else
                                if opcode s= opiter_op_i32_rem_s
                                then
                                  Ok (Some (Types_ValueType_I32,
                                    Types_ValueType_I32))
                                else
                                  if opcode s= opiter_op_i32_rem_u
                                  then
                                    Ok (Some (Types_ValueType_I32,
                                      Types_ValueType_I32))
                                  else
                                    if opcode s= opiter_op_i32_and
                                    then
                                      Ok (Some (Types_ValueType_I32,
                                        Types_ValueType_I32))
                                    else
                                      if opcode s= opiter_op_i32_or
                                      then
                                        Ok (Some (Types_ValueType_I32,
                                          Types_ValueType_I32))
                                      else
                                        if opcode s= opiter_op_i32_xor
                                        then
                                          Ok (Some (Types_ValueType_I32,
                                            Types_ValueType_I32))
                                        else
                                          if opcode s= opiter_op_i32_shl
                                          then
                                            Ok (Some (Types_ValueType_I32,
                                              Types_ValueType_I32))
                                          else
                                            if opcode s= opiter_op_i32_shr_s
                                            then
                                              Ok (Some (Types_ValueType_I32,
                                                Types_ValueType_I32))
                                            else
                                              if opcode s= opiter_op_i32_shr_u
                                              then
                                                Ok (Some (Types_ValueType_I32,
                                                  Types_ValueType_I32))
                                              else
                                                if opcode s= opiter_op_i32_rotl
                                                then
                                                  Ok (Some
                                                    (Types_ValueType_I32,
                                                    Types_ValueType_I32))
                                                else
                                                  if opcode s=
                                                    opiter_op_i32_rotr
                                                  then
                                                    Ok (Some
                                                      (Types_ValueType_I32,
                                                      Types_ValueType_I32))
                                                  else
                                                    if opcode s=
                                                      opiter_op_i64_eq
                                                    then
                                                      Ok (Some
                                                        (Types_ValueType_I64,
                                                        Types_ValueType_I32))
                                                    else
                                                      if opcode s=
                                                        opiter_op_i64_ne
                                                      then
                                                        Ok (Some
                                                          (Types_ValueType_I64,
                                                          Types_ValueType_I32))
                                                      else
                                                        if opcode s=
                                                          opiter_op_i64_lt_s
                                                        then
                                                          Ok (Some
                                                            (Types_ValueType_I64,
                                                            Types_ValueType_I32))
                                                        else
                                                          if opcode s=
                                                            opiter_op_i64_lt_u
                                                          then
                                                            Ok (Some
                                                              (Types_ValueType_I64,
                                                              Types_ValueType_I32))
                                                          else
                                                            if opcode s=
