(** [veriwasm::opiter::convert_types]:
    Source: 'src/opiter.rs', lines 1063:0-1143:1 *)
Definition opiter_convert_types
  (opcode : u8) : result (option (types_ValueType_t * types_ValueType_t)) :=
  if opcode s= opiter_op_i32_eqz
  then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
  else
    if opcode s= opiter_op_i32_clz
    then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
    else
      if opcode s= opiter_op_i32_ctz
      then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
      else
        if opcode s= opiter_op_i32_popcnt
        then Ok (Some (Types_ValueType_I32, Types_ValueType_I32))
        else
          if opcode s= opiter_op_i64_clz
          then Ok (Some (Types_ValueType_I64, Types_ValueType_I64))
          else
            if opcode s= opiter_op_i64_ctz
            then Ok (Some (Types_ValueType_I64, Types_ValueType_I64))
            else
              if opcode s= opiter_op_i64_popcnt
              then Ok (Some (Types_ValueType_I64, Types_ValueType_I64))
              else
                if opcode s= opiter_op_f32_abs
                then Ok (Some (Types_ValueType_F32, Types_ValueType_F32))
                else
                  if opcode s= opiter_op_f32_neg
                  then Ok (Some (Types_ValueType_F32, Types_ValueType_F32))
                  else
                    if opcode s= opiter_op_f32_ceil
                    then Ok (Some (Types_ValueType_F32, Types_ValueType_F32))
                    else
                      if opcode s= opiter_op_f32_floor
                      then Ok (Some (Types_ValueType_F32, Types_ValueType_F32))
                      else
                        if opcode s= opiter_op_f32_trunc
                        then
                          Ok (Some (Types_ValueType_F32, Types_ValueType_F32))
                        else
                          if opcode s= opiter_op_f32_nearest
                          then
                            Ok (Some (Types_ValueType_F32,
                              Types_ValueType_F32))
                          else
                            if opcode s= opiter_op_f32_sqrt
                            then
                              Ok (Some (Types_ValueType_F32,
                                Types_ValueType_F32))
                            else
                              if opcode s= opiter_op_f64_abs
                              then
                                Ok (Some (Types_ValueType_F64,
                                  Types_ValueType_F64))
                              else
                                if opcode s= opiter_op_f64_neg
                                then
                                  Ok (Some (Types_ValueType_F64,
                                    Types_ValueType_F64))
                                else
                                  if opcode s= opiter_op_f64_ceil
                                  then
                                    Ok (Some (Types_ValueType_F64,
                                      Types_ValueType_F64))
                                  else
                                    if opcode s= opiter_op_f64_floor
                                    then
                                      Ok (Some (Types_ValueType_F64,
                                        Types_ValueType_F64))
                                    else
                                      if opcode s= opiter_op_f64_trunc
                                      then
                                        Ok (Some (Types_ValueType_F64,
                                          Types_ValueType_F64))
                                      else
                                        if opcode s= opiter_op_f64_nearest
                                        then
                                          Ok (Some (Types_ValueType_F64,
                                            Types_ValueType_F64))
                                        else
                                          if opcode s= opiter_op_f64_sqrt
                                          then
                                            Ok (Some (Types_ValueType_F64,
                                              Types_ValueType_F64))
                                          else
                                            if opcode s= opiter_op_i64_eqz
                                            then
                                              Ok (Some (Types_ValueType_I64,
                                                Types_ValueType_I32))
                                            else
                                              if opcode s=
                                                opiter_op_i32_wrap_i64
                                              then
                                                Ok (Some (Types_ValueType_I64,
                                                  Types_ValueType_I32))
                                              else
                                                if opcode s=
                                                  opiter_op_i32_trunc_f32_s
                                                then
                                                  Ok (Some
                                                    (Types_ValueType_F32,
                                                    Types_ValueType_I32))
                                                else
                                                  if opcode s=
                                                    opiter_op_i32_trunc_f32_u
                                                  then
                                                    Ok (Some
                                                      (Types_ValueType_F32,
                                                      Types_ValueType_I32))
                                                  else
                                                    if opcode s=
                                                      opiter_op_i32_reinterpret_f32
                                                    then
                                                      Ok (Some
                                                        (Types_ValueType_F32,
                                                        Types_ValueType_I32))
                                                    else
                                                      if opcode s=
                                                        opiter_op_i32_trunc_f64_s
                                                      then
                                                        Ok (Some
                                                          (Types_ValueType_F64,
                                                          Types_ValueType_I32))
                                                      else
                                                        if opcode s=
                                                          opiter_op_i32_trunc_f64_u
                                                        then
                                                          Ok (Some
                                                            (Types_ValueType_F64,
                                                            Types_ValueType_I32))
                                                        else
                                                          if opcode s=
                                                            opiter_op_i64_extend_i32_s
                                                          then
                                                            Ok (Some
                                                              (Types_ValueType_I32,
                                                              Types_ValueType_I64))
                                                          else
                                                            if opcode s=
                                                              opiter_op_i64_extend_i32_u
                                                            then
                                                              Ok (Some
                                                                (Types_ValueType_I32,
                                                                Types_ValueType_I64))
                                                            else
                                                              if opcode s=
                                                                opiter_op_i64_trunc_f32_s
                                                              then
                                                                Ok (Some
                                                                  (Types_ValueType_F32,
                                                                  Types_ValueType_I64))
                                                              else
                                                                if opcode s=
                                                                  opiter_op_i64_trunc_f32_u
                                                                then
                                                                  Ok (Some
                                                                    (Types_ValueType_F32,
                                                                    Types_ValueType_I64))
                                                                else
                                                                  if opcode s=
                                                                    opiter_op_i64_trunc_f64_s
                                                                  then
                                                                    Ok (Some
                                                                    (Types_ValueType_F64,
                                                                    Types_ValueType_I64))
                                                                  else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_i64_trunc_f64_u
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_F64,
                                                                    Types_ValueType_I64))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_i64_reinterpret_f64
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_F64,
                                                                    Types_ValueType_I64))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f32_convert_i32_s
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I32,
                                                                    Types_ValueType_F32))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f32_convert_i32_u
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I32,
                                                                    Types_ValueType_F32))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f32_reinterpret_i32
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I32,
                                                                    Types_ValueType_F32))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f32_convert_i64_s
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I64,
                                                                    Types_ValueType_F32))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f32_convert_i64_u
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I64,
                                                                    Types_ValueType_F32))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f32_demote_f64
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_F64,
                                                                    Types_ValueType_F32))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f64_convert_i32_s
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I32,
                                                                    Types_ValueType_F64))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f64_convert_i32_u
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I32,
                                                                    Types_ValueType_F64))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f64_convert_i64_s
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I64,
                                                                    Types_ValueType_F64))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f64_convert_i64_u
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I64,
                                                                    Types_ValueType_F64))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f64_reinterpret_i64
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_I64,
                                                                    Types_ValueType_F64))
                                                                    else
                                                                    if opcode
                                                                    s=
                                                                    opiter_op_f64_promote_f32
                                                                    then
                                                                    Ok (Some
                                                                    (Types_ValueType_F32,
                                                                    Types_ValueType_F64))
                                                                    else
                                                                    Ok None
.

(** [veriwasm::types::{core::cmp::PartialEq<veriwasm::types::ValueType> for veriwasm::types::ValueType}::eq]:
    Source: 'src/types.rs', lines 22:4-30:5 *)
Definition types_ValueType_Insts_CoreCmpPartialEqValueType_eq
  (self : types_ValueType_t) (other : types_ValueType_t) : result bool :=
  match self with
  | Types_ValueType_I32 =>
    match other with
    | Types_ValueType_I32 => Ok true
    | Types_ValueType_I64 => Ok false
    | Types_ValueType_F32 => Ok false
    | Types_ValueType_F64 => Ok false
    end
  | Types_ValueType_I64 =>
    match other with
    | Types_ValueType_I32 => Ok false
    | Types_ValueType_I64 => Ok true
    | Types_ValueType_F32 => Ok false
    | Types_ValueType_F64 => Ok false
    end
  | Types_ValueType_F32 =>
    match other with
    | Types_ValueType_I32 => Ok false
    | Types_ValueType_I64 => Ok false
    | Types_ValueType_F32 => Ok true
    | Types_ValueType_F64 => Ok false
    end
  | Types_ValueType_F64 =>
    match other with
    | Types_ValueType_I32 => Ok false
    | Types_ValueType_I64 => Ok false
    | Types_ValueType_F32 => Ok false
    | Types_ValueType_F64 => Ok true
    end
  end
.

(** [veriwasm::opiter::cur_polymorphic]:
    Source: 'src/opiter.rs', lines 358:0-364:1 *)
Definition opiter_cur_polymorphic (st : opiter_OpIterState_t) : result bool :=
  let n := alloc_vec_Vec_len st.(opiter_OpIterState_ctrls) in
  if n s= 0%usize
  then Ok false
  else (
    i <- usize_sub n 1%usize;
    c <-
      alloc_vec_Vec_index (core_slice_index_SliceIndexUsizeSliceInst
        opiter_Ctrl_t) st.(opiter_OpIterState_ctrls) i;
    Ok c.(opiter_Ctrl_polymorphic_base))
.

